script:
frappe.ui.form.on("Client script Practice", {
    refresh(frm) {
        frappe.msgprint("Client Script Loaded");
    }
});

frappe.ui.form.on("Appointment", {
    date_time(frm) {
        if (
            frm.doc.date_time &&
            frm.doc.date_time < frappe.datetime.now_datetime()
        ) {
            frappe.msgprint("Appointment date cannot be in the past.");
            frm.set_value("date_time", null);
        }
    }
});

frappe.ui.form.on("Appointment", {
    setup(frm) {
        frm.set_query("doctor_name", function () {
            return {
                filters: {
                    availability: 1
                }
            };
        });
    }
});

frappe.ui.form.on('Customers', {
    setup: function(frm) {
        frm.set_query("territory", function() {
            return {
                filters: {
                    "territory_name": "India" // ensure exact field name in Territory
                }
            };
        });
    }
});

frappe.ui.form.on('User', {
    refresh(frm) {
        frm.add_custom_button('Send Welcome Email', function() {
            frappe.msgprint('Email Sent!');
        }, 'Actions');
    }
});
